def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

print("Starting systematic search for k=2 solutions...")
solutions = []

# Iterate over exponents 1 <= e1, e2 <= 4
for e1 in range(1, 5):
    for e2 in range(1, 5):
        # Calculate the required value R
        R = (12 * e1 + 1) * (12 * e2 + 1)

        # Factor R
        factors = prime_factorization(R)

        # Condition 1: R must have exactly two distinct prime factors
        if len(factors) != 2:
            continue

        # Condition 2: The exponents in the factorization of R must match {e1, e2}
        exponents = sorted(factors.values())
        target_exponents = sorted([e1, e2])

        if exponents == target_exponents:
            p1 = list(factors.keys())[0]
            p2 = list(factors.keys())[1]

            # We found a match. Check if the assignment leads to the required form.
            # We need to map {p1, p2} to {e1, e2} such that the exponents match.

            # Case 1: p1 has exponent e1, p2 has exponent e2
            if factors[p1] == e1 and factors[p2] == e2:
                n = p1**e1 * p2**e2
                solutions.append({
                    "e1": e1, "e2": e2, 
                    "p1": p1, "p2": p2, 
                    "n": n, "R": R
                })

            # Case 2: p1 has exponent e2, p2 has exponent e1
            # This is only needed if e1 != e2, otherwise it's covered above.
            elif e1 != e2 and factors[p1] == e2 and factors[p2] == e1:
                n = p1**e2 * p2**e1
                solutions.append({
                    "e1": e1, "e2": e2, 
                    "p1": p2, "p2": p1, # Reorder to fit p1^e1 p2^e2 form if needed, but tracking the actual match is clearer.
                    "n": n, "R": R
                })

# Print results
if solutions:
    print("\n--- Found Solutions ---")
    for sol in solutions:
        # For reporting, let's use the canonical form p_a^e_a p_b^e_b where the exponents are e1 and e2
        # We just need to state the final n.
        print(f"R = {sol['R']}: Corresponds to n = {sol['n']}")
else:
    print("\nNo solutions found in the range 1 <= e1, e2 <= 4.")
